// Clean record of each call / delivery update. Connect Google Sheets, Airtable or email after this node.
return $input.all().map(item => {
  const b = item.json.body || {};
  return { json: {
    time: new Date().toISOString(),
    type: b.source,
    from: b.From || '',
    to: b.To || '',
    status: b.CallStatus || b.MessageStatus || b.SmsStatus || '',
    callSid: b.CallSid || '',
    messageSid: b.MessageSid || '',
    recordingUrl: b.RecordingUrl || ''
  }};
});
